import {example,compare} from './engine.mjs';
let lang='tr',current=[],x=structuredClone(example);
const en={prototype:'First release',eyebrow:'CALCULATE BEFORE YOU SELL',headline:'Grow your campaign.<br>Protect your profit.',lead:'Discounts, bundles or free shipping. Compare four options with the same costs and make an informed decision.',note:'More revenue does not<br>always mean more profit.',inputs:'01 / Product & costs',example:'Load example',sample:'Illustrative starting values. All amounts in TRY.',settings:'VAT & commission settings',assumptions:'Product sales and customer delivery charges include product VAT. Expense VAT is assumed recoverable. Profit is before income/corporate tax.',calculate:'Compare scenarios ↗',privacy:'Calculated in your browser. Your inputs are neither sent to a server nor saved.',results:'02 / Campaign comparison',breakdown:'Where does the money go?',netnote:'Revenue and costs below exclude VAT. Break-even is the order’s product total after discount; customer delivery is separate.',method:'Method & limitations',formula:'Profit = revenue excluding VAT − product cost − commission − shipping − other costs. Margin = profit / revenue excluding VAT. A bundle contains two of the same product; shipping and other costs apply per order.',limits:'Scenario calculation, not a sales forecast. Include returns, advertising and platform fees in other costs as appropriate. Shipping tiers and variable commission schedules are not applied automatically.',footer:'One product, one clear decision. Now see your whole store.',cta:'Explore Makskar ↗'};
const tr={};document.querySelectorAll('[data-t]').forEach(e=>tr[e.dataset.t]=e.innerHTML);
Object.assign(tr,{prototype:'Sürüm 0.2',sample:'Başlangıç rakamları örnektir. Seçilen para birimi tüm tutarlara uygulanır.',settings:'Komisyon ayarları ve varsayımlar',netnote:'Dağılım KDV hariçtir. İlk kâra geçiş, indirim sonrası ürün toplamıdır; müşteri kargosu ayrıca tutulur. Gösterim iki ondalığa yuvarlanır.',limits:'Barem ücretlerini kendi anlaşmanıza göre girin; güncel pazaryeri tarifesi değildir. Barem, müşteri kargosu hariç indirimli ürün toplamına uygulanır. Sabit modda ikili paketin kendi kargo alanı kullanılır. Sonraki barem geçişleri tekrar zarara yol açabilir. Para birimi seçimi kur dönüşümü yapmaz.',formula:'Kâr = KDV hariç gelir − ürün maliyeti − komisyon − kargo − platform − paketleme − diğer giderler. Marj = kâr / KDV hariç gelir. İkili pakette yalnızca ürün maliyeti ikiyle çarpılır; diğer giderler sipariş başınadır.'});
Object.assign(en,{prototype:'Version 0.2',sample:'Illustrative inputs. Selected currency applies to all amounts.',settings:'Commission settings & assumptions',netnote:'Breakdown excludes VAT. First non-loss price is the discounted product total, excluding customer delivery. Display rounded to two decimals.',limits:'Enter your own shipping contract; tiers are not live marketplace tariffs. Tiers use discounted product total excluding customer delivery. Fixed mode uses the separate bundle shipping field. Later tiers may cause losses again. Currency selection does not convert amounts.',formula:'Profit = net revenue − goods − commission − shipping − platform − packaging − other costs. Margin = profit / net revenue. Only product cost doubles in a two-item bundle; other expenses apply per order.'});
const names={tr:['Normal satış','İndirimli satış','İkili paket','Ücretsiz kargo'],en:['Standard sale','Discounted sale','Two-item bundle','Free shipping']};
const labels={price:['Satış fiyatı · KDV dahil','Sale price · incl. VAT'],cost:['Alış maliyeti · adet başına','Purchase cost · per item'],shipping:['Kargo gideri · sipariş','Shipping cost · per order'],shippingIncome:['Müşteriden alınan kargo','Customer delivery charge'],other:['Diğer giderler · sipariş','Other costs · per order'],rate:['Komisyon oranı (%)','Commission rate (%)'],discount:['Tekli satış indirimi (%)','Single-item discount (%)'],bundleDiscount:['Paket indirimi (%)','Bundle discount (%)'],bundleShipping:['İkili paketin kargo gideri','Bundle shipping cost'],vat:['Ürün KDV oranı (%)','Product VAT (%)'],costVat:['Alış KDV oranı (%)','Purchase VAT (%)'],shippingVat:['Kargo KDV oranı (%)','Shipping VAT (%)'],otherVat:['Diğer gider KDV oranı (%)','Other cost VAT (%)'],commissionVat:['Komisyon KDV oranı (%)','Commission VAT (%)']};
Object.assign(labels,{platform:['Pazaryeri / platform bedeli · sipariş','Marketplace / platform fee · per order'],packaging:['Paketleme gideri · sipariş','Packaging · per order'],platformVat:['KDV oranı (%)','VAT (%)'],packagingVat:['KDV oranı (%)','VAT (%)'],bundleShippingVat:['KDV oranı (%)','VAT (%)']});
const t=(a,b)=>lang==='tr'?a:b, money=n=>n===null?'—':new Intl.NumberFormat(lang==='tr'?'tr-TR':'en-GB',{style:'currency',currency:x.currency,maximumFractionDigits:2}).format(n);
function field(k){return `<div class="field"><label for="${k}">${labels[k][lang==='tr'?0:1]}</label><input id="${k}" name="${k}" type="number" inputmode="decimal" step="0.01" min="${k==='price'?'0.01':'0'}" ${['vat','costVat','shippingVat','otherVat','commissionVat','platformVat','packagingVat','bundleShippingVat','rate','discount','bundleDiscount'].includes(k)?'max="100"':''} value="${x[k]??(k==='bundleShippingVat'?x.shippingVat:0)}" required></div>`}
function choice(k,label,a,b){return `<div class="field"><label for="${k}">${label}</label><select id="${k}" name="${k}"><option value="true" ${(x[k]??x.included)?'selected':''}>${a}</option><option value="false" ${!(x[k]??x.included)?'selected':''}>${b}</option></select></div>`}
function expense(k){const vk=k+'Vat';const ik=k+'Included';return `<div class="expense">${field(k)}<div class="vat-row">${choice(ik,t('Tutar türü','Amount basis'),t('KDV dahil','VAT included'),t('KDV hariç','VAT excluded'))}${field(vk)}</div></div>`}
function select(k,label,options){return `<div class="field"><label for="${k}">${label}</label><select id="${k}" name="${k}">${options.map(([v,l])=>`<option value="${v}" ${x[k]===v?'selected':''}>${l}</option>`).join('')}</select></div>`}
function tierEditor(){return `<div id="tiers" ${x.shippingMode==='tiers'?'':'hidden'}><p class="small">${t('İndirim sonrası KDV dahil ürün toplamına göre. Alt sınır dahil, sonraki sınır hariçtir. Son aralık sınırsızdır. Bunlar örnek ücretlerdir; kendi anlaşmanızı girin.','Based on discounted product total including VAT. Lower bound inclusive, next bound exclusive; last band unlimited. Illustrative fees: enter your own contract.')}</p>${x.tiers.map((b,i)=>`<div class="tier-row"><label>${t('Alt sınır','From')}<input type="number" min="0" step="0.01" name="tierMin${i}" value="${b.min}" ${i===0?'readonly':''} required></label><label>${t('Kargo ücreti','Shipping fee')}<input type="number" min="0" step="0.01" name="tierCost${i}" value="${b.cost}" required></label><button type="button" data-remove="${i}" ${i===0?'disabled':''} aria-label="${t('Aralığı sil','Remove band')}">×</button></div>`).join('')}<button type="button" id="addTier">${t('+ Aralık ekle','+ Add band')}</button><p class="small">${t('Barem ücretleri yukarıdaki kargo KDV ayarını kullanır.','Tier fees use the shipping VAT settings above.')}</p></div>`}
function setup(){document.documentElement.lang=lang;document.querySelectorAll('[data-t]').forEach(e=>e.innerHTML=(lang==='tr'?tr:en)[e.dataset.t]);document.querySelector('#language').textContent=lang==='tr'?'EN':'TR';document.querySelector('#fields').innerHTML=select('currency',t('Para birimi · kur dönüşümü yapılmaz','Currency · no exchange conversion'),[['TRY','TL / TRY'],['EUR','EUR / €'],['USD','USD / $']])+field('price')+field('vat')+expense('cost')+expense('platform')+expense('packaging')+expense('other')+field('shippingIncome')+field('rate')+`<div class="subhead">${t('Kargo maliyeti','Shipping cost')}</div>`+expense('shipping')+select('shippingMode',t('Kargo hesaplama yöntemi','Shipping method'),[['fixed',t('Sabit ücret','Fixed fee')],['tiers',t('Fiyat aralığına göre (barem)','By order value (tiers)')]])+tierEditor()+`<div class="subhead">${t('Kampanya seçenekleri','Campaign options')}</div>`+field('discount')+field('bundleDiscount')+choice('bundleOverride',t('İkili pakette ayrı kargo ücreti kullan','Use a separate bundle shipping fee'),t('Evet · ayrı ücret','Yes · override'),t('Hayır · aynı barem','No · same tiers'))+expense('bundleShipping');document.querySelector('#settings').innerHTML=field('commissionVat')+choice('commissionIncluded',t('Girilen komisyon oranı','Entered commission rate'),t('Komisyon KDV’si dahil','Includes commission VAT'),t('Komisyon KDV’si hariç','Excludes commission VAT'))+choice('baseGross',t('Komisyon matrahı','Commission basis'),t('KDV dahil satış','Sales including VAT'),t('KDV hariç satış','Sales excluding VAT'))+choice('commissionShipping',t('Müşteri kargosu komisyona dahil mi?','Commission on customer delivery?'),t('Evet','Yes'),t('Hayır','No'));
 document.querySelector('#shippingMode').onchange=()=>{read();setup()};document.querySelector('#addTier').onclick=()=>{read();x.tiers.push({min:x.tiers.at(-1).min+300,cost:x.tiers.at(-1).cost});setup()};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{read();x.tiers.splice(Number(b.dataset.remove),1);setup()});
 document.querySelector('#detail').innerHTML=names[lang].map((n,i)=>`<option value="${i}">${n}</option>`).join('');render()}
function read(){const data=new FormData(document.querySelector('#inputs'));for(const [k,v] of data.entries()){if(k.startsWith('tier'))continue;if(k.endsWith('Included')||['bundleOverride','baseGross','commissionShipping'].includes(k))x[k]=v==='true';else if(['currency','shippingMode'].includes(k))x[k]=v;else x[k]=v.trim()===''?NaN:Number(v);}x.tiers=x.tiers.map((b,i)=>({min:Number(data.get('tierMin'+i)),cost:Number(data.get('tierCost'+i))}));}
function render(){try{current=compare(x);document.querySelector('#error').textContent='';}catch{document.querySelector('#state').textContent=t('Hesaplanamadı','Invalid inputs');document.querySelector('#cards').innerHTML='';document.querySelector('#bars').innerHTML='';document.querySelector('#insight').textContent='';current=[];document.querySelector('#error').textContent=t('Barem alt sınırları 0’dan başlayıp artmalıdır. Lütfen geçerli, sıfır veya pozitif tutarlar girin. Satış fiyatı sıfırdan büyük, oranlar 0–100 arasında olmalı.','Tier bounds must start at zero and increase. Enter valid non-negative amounts. Sale price must be positive and percentages must be between 0 and 100.');return}
 const best=Math.max(...current.map(s=>s.unit));const bestI=current.findIndex(s=>s.unit===best);const extra=current[1].profit>0&&current[0].profit>0?Math.max(0,(current[0].profit/current[1].profit-1)*100):null;
 document.querySelector('#state').textContent=t('● Hesaplandı','● Calculated');
 document.querySelector('#insight').innerHTML=`<strong>${best>0?t('Ürün başına en yüksek kâr: ','Highest profit per item: ')+names[lang][bestI]:t('Bu maliyetlerle kârlı bir seçenek yok.','No profitable option with these costs.')}</strong>${extra===null?t('Zarardaki bir satışın adedini artırmak zararı büyütür.','Increasing the volume of a loss-making sale increases the loss.'):t('İndirimli satışta aynı toplam kâr için yaklaşık %','To match standard-sale total profit, discounted sales need about ')+extra.toFixed(1)+t(' daha fazla sipariş gerekir. Bu bir satış tahmini değildir.','% more orders. This is not a sales forecast.')}`;
 document.querySelector('#cards').innerHTML=current.map((s,i)=>{const row=(a,b)=>`<div class="metric"><span>${a}</span><b>${b}</b></div>`;return `<article class="scenario ${s.unit===best&&best>0?'best':''}">${s.unit===best&&best>0?`<span class="badge">${t('EN YÜKSEK BİRİM KÂR','BEST PER ITEM')}</span>`:''}<h3>${names[lang][i]}</h3><div class="caption">${s.q} ${t('adet · ürün toplamı','item(s) · product total')} ${money(s.sales)}</div><div class="profit ${s.profit<0?'loss':''}">${money(s.profit)}</div><div class="caption">${t('Sipariş başına kâr · vergi öncesi','Profit per order · before income tax')}</div><div class="metrics">${row(t('Ürün başına kâr','Profit per item'),money(s.unit))}${row(t('Kâr marjı','Profit margin'),s.margin.toFixed(2)+'%')}${row(t('İlk kâra geçiş ürün toplamı','First non-loss product total'),s.breakEven===null?t('Mümkün değil','Not attainable'):money(s.breakEven))}${row(t('Uygulanan kargo (net)','Applied shipping (net)'),money(s.shipping))}${s.tiered?`<p class="small">${t('Barem: ','Tier: ')}${money(s.bandMin)} ≤ ${t('ürün toplamı','product total')} ${s.bandMax===null?'': '&lt; '+money(s.bandMax)}</p>`:''}${s.laterLoss?`<p class="small loss">${t('Dikkat: sonraki barem geçişinde yeniden zarar oluşabilir.','A later tier change can make this loss-making again.')}</p>`:''}${row(t('Normal satışa göre / adet','Vs standard / item'),money(s.unit-current[0].unit))}</div></article>`}).join('');bars();}
function bars(){const s=current[Number(document.querySelector('#detail').value)||0];if(!s)return;const items=[[t('Net gelir','Net revenue'),s.revenue],[t('Ürün maliyeti','Product cost'),s.goods],[t('Komisyon','Commission'),s.commission],[t('Kargo','Shipping'),s.shipping],[t('Platform','Platform fee'),s.platform],[t('Paketleme','Packaging'),s.packaging],[t('Diğer gider','Other costs'),s.other],[t('Kâr / zarar','Profit / loss'),s.profit]];document.querySelector('#bars').innerHTML=items.map(([label,v])=>`<div class="barrow"><span>${label}</span><div class="track"><div class="fill" style="width:${Math.min(100,Math.abs(v)/Math.max(1,s.revenue)*100)}%"></div></div><b class="${v<0?'loss':''}">${money(v)}</b></div>`).join('')}
document.querySelector('#inputs').addEventListener('submit',e=>{e.preventDefault();read();render()});document.querySelector('#inputs').addEventListener('input',()=>document.querySelector('#state').textContent=t('Değişiklikler bekliyor','Changes pending'));document.querySelector('#language').onclick=()=>{if(document.querySelector('#inputs').checkValidity())read();lang=lang==='tr'?'en':'tr';setup()};document.querySelector('#example').onclick=()=>{x=structuredClone(example);setup()};document.querySelector('#detail').onchange=bars;setup();
